ee:message.ee:set-payload:
%dw 2.0
import p from Mule
output application/json
var out = payload.Envelope.Body.RegistroPositivoResponse.RegistroPositivoResult
---
{
	"RegistroPositivoResponse": {
		"Header":  {
			"ID": vars.correlationID,
			"Operation": p('imei.insertPositiveRecord.operation'),
			"RequestSystem": p('imei.insertPositiveRecord.out.requestSystem'),
			"Version": p('imei.insertPositiveRecord.version'),     
			"Type": p('imei.insertPositiveRecord.out.type'), 
			"ReqType": p('imei.insertPositiveRecord.reqType'),
			"RequestDateTime": vars.requestDateTime,
			"ResponseDateTime": now()   
    	},
		"Body": { 
			"Code": "00",
      		"Description": "OK",
      		"RegistroPositivoResponse": {
        		"RegistroPositivoResult": out
      		}
		}
	}
}

%dw 2.0
import p from Mule
output application/json
---
{
	"RegistroPositivoResponse": {
		"Header":  {
	      "ID": vars.correlationID,
	      "Operation": p('imei.insertPositiveRecord.operation'),
	      "RequestSystem": p('imei.insertPositiveRecord.out.requestSystem'),
	      "Version": p('imei.insertPositiveRecord.version'),     
	      "Type": p('imei.insertPositiveRecord.out.type'), 
	      "ReqType": p('imei.insertPositiveRecord.reqType'),
	      "RequestDateTime": vars.requestDateTime,
	      "ResponseDateTime": now()   
	    },
		"Body": { 
			"Code": "01",
	      	"Description": "Error al invocar WS Registro Positivo VMR"
		}		
	}
}
